    /// <summary>
    /// Modified field logic
    /// </summary>
    /// <param name="_fieldId">
    /// The instance of <c>FieldId</c> class.
    /// </param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCBCTInvoiceLine, ItemId):
                this.assignFinancialDimension();
                break;
        }
    }

    /// <summary>
    /// Set financial dimension on the line. Initially copied from the Charge through header and updated with the default Department dimensions from the Service Item
    /// </summary>
    private void assignFinancialDimension()
    {
        InventTable                         inventTable = InventTable::find(this.ItemId);
        DimensionAttributeRecId             departmentDimensionAttributeRecId = DimensionAttribute::findByName('Department').RecId;

        if (METCBCTInvoiceLine::checkItemHasDepartmentDimension(inventTable.ItemId))
        {
            this.setFinancialDimension(inventTable.DefaultDimension,departmentDimensionAttributeRecId);
        }
        //else if (this.CustVend == CustVendACType::Cust)
        else if (this.VendCustType == METCBCTVendCust::Cust)
        {
            //If the current line is of type customer then default department from the item of line type vendor for the charge through invoice 
            METCBCTInvoiceLine      invoiceLineVendor;
            select firstonly ItemId 
                from invoiceLineVendor
                where invoiceLineVendor.HeaderNumber == this.HeaderNumber 
                && invoiceLineVendor.VendCustType == METCBCTVendCust::Vend;
            if (invoiceLineVendor.ItemId && METCBCTInvoiceLine::checkItemHasDepartmentDimension(invoiceLineVendor.ItemId))
            {
                this.setFinancialDimension(InventTable::find(invoiceLineVendor.ItemId).DefaultDimension,departmentDimensionAttributeRecId);
            }
        }
    }

    /// <summary>
    /// Init dimension when line is created and item is defaulted from header with default line type of customer
    /// </summary>
    /// <param name="_defaultItemId">
    /// The instance of <c>ItemId</c> class.
    /// </param>
    /// <param name="_headerDefaultDimension">
    /// The instance of <c>DimensionDefault</c> class.
    /// </param>
    /// <returns>
    /// DimensionDefault object for financial dimension.
    /// </returns>
    public static DimensionDefault initFinancialDimension(ItemId    _defaultItemId, DimensionDefault    _headerDefaultDimension)
    {
        InventTable                         inventTable = InventTable::find(_defaultItemId);
        DimensionAttributeRecId             departmentDimensionAttributeRecId = DimensionAttribute::findByName('Department').RecId;

        if (METCBCTInvoiceLine::checkItemHasDepartmentDimension(inventTable.ItemId))
        {
            return DimensionDefaultFacade::serviceReplaceAttributeValue(_headerDefaultDimension,inventTable.DefaultDimension,departmentDimensionAttributeRecId);
        }
        return 0;
    }

/// <summary>
/// Set financial dimension
/// </summary>
/// <param name="_itemDefaultDimension">
/// The instance of <c>DimensionDefault</c> class.
/// </param>
/// <param name="_departmentDimensionAttributeRecId">
/// The instance of <c>DimensionAttributeRecId</c> class.
/// </param>
public void setFinancialDimension(DimensionDefault  _itemDefaultDimension, DimensionAttributeRecId  _departmentDimensionAttributeRecId)
{
    this.FinancialDimension = DimensionDefaultFacade::serviceReplaceAttributeValue(this.FinancialDimension,_itemDefaultDimension,_departmentDimensionAttributeRecId);
}

    /// <summary>
    ///  Check if the item has department dimension defined.
    /// </summary>
    /// <param name="_itemId">
    /// The instance of <c>ItemId</c> class.
    /// </param>
    /// <returns>
    /// True if item has department dimension.
    /// </returns>
    public Static boolean checkItemHasDepartmentDimension(ItemId   _itemId)
    {
        boolean                             ret;
        InventTable                         inventTable = InventTable::find(_itemId);
        DimensionAttributeValueSetStorage   dimStorage;
        DimensionValue                      departmentDimensionValue;
        DimensionAttributeRecId             departmentDimensionAttributeRecId = DimensionAttribute::findByName('Department').RecId;

        dimStorage = DimensionAttributeValueSetStorage::find(inventTable.DefaultDimension);
        departmentDimensionValue = dimStorage.getDisplayValueByDimensionAttribute(departmentDimensionAttributeRecId);

        ret = departmentDimensionValue ? true : false;

        return ret;
    }

/// <summary>
/// Init value for the table fields 
/// </summary>
public void initValue()
{
    this.Qty = 1;
    this.InventTransId = NumberSeq::newGetNum(InventParameters::numRefInventTransId()).num();
    super();
}

    /// <summary>
    ///  Find the related record of METCBCTInvoiceHeaderTable.
    /// </summary>
    /// <returns>
    /// returns instance of METCBCTInvoiceHeaderTable.
    /// </returns>
    public METCBCTInvoiceHeaderTable    ctInvoiceHeaderTable()
    {
        METCBCTInvoiceHeaderTable       cTInvoiceHeaderTable;

        select cTInvoiceHeaderTable 
            where cTInvoiceHeaderTable.Number == this.HeaderNumber;

        return cTInvoiceHeaderTable;
    }

    /// <summary>
    ///  Returns the METVendTable record linked to the current buffer.
    /// </summary>
    /// <returns>
    ///  Returns instance of METVendTable.
    /// </returns>
    public METVendTable     MetVendTable()
    {
        METVendTable                metVendTable;
        METCBCTInvoiceHeaderTable   cTInvoiceHeaderTable = this.ctInvoiceHeaderTable();

        select metVendTable 
            where metVendTable.AccountNum == cTInvoiceHeaderTable.VendorAccount;

        return metVendTable;
    }

    /// <summary>
    /// Insert logic
    /// </summary>
    public void insert()
    {
        if (!this.InventTransId)
        {
            this.InventTransId = NumberSeq::newGetNum(InventParameters::numRefInventTransId()).num();
        }
        super();

        switch (this.VendCustType)
        {
            case METCBCTVendCust::Vend :
                this.createMarkupTransVend(this.ctInvoiceHeaderTable());
                this.updateItemTaxGroup();
                break;
        /*In case of customer line we create auto charges same as in case of vendor and then cleanup the records which do not have 
        corresponding sales markup code defined in METCBCTPricingConditionChargesLinkTable table*/
            case METCBCTVendCust::Cust :
                this.createMarkupTransVend(this.ctInvoiceHeaderTable()); //Create as per vendor
                this.updateItemTaxGroup();
                this.cleanupCustMarkUp();
                break;
        }
    }

/// <summary>
/// Insert auto charges 
/// </summary>
/// <param name="_ctInvoiceHeaderTable">
/// The instance of <c>METCBCTInvoiceHeaderTable</c> table.
/// </param>
void createMarkupTransVend(METCBCTInvoiceHeaderTable    _ctInvoiceHeaderTable)
{
    Markup::insertMarkupTrans(HeadingLine::Line,
                          MarkupModuleType::Vend,
                          this,
                          _ctInvoiceHeaderTable.VendorAccount,
                          _ctInvoiceHeaderTable.vendTable().MarkupGroup,
                          _ctInvoiceHeaderTable.CurrencyCode,
                          _ctInvoiceHeaderTable.vendTable().languageId(),
                          this.ItemId,
                          this.inventTable().purchMarkupGroup(),
                         (this.Amount < 0)); // invert sign on creditnotes
}

/// <summary>
/// Find the related InventTable record
/// </summary>
/// <returns>
/// Returns instance of InventTable.
/// </returns>
public InventTable inventTable()
{
    return InventTable::find(this.ItemId);
}

    /// <summary>
    /// Update the item tax group on the markup trans.
    /// </summary>
    public void updateItemTaxGroup()
    {
        //Update auto charges item GST tax code
        MarkupTrans     markUpTrans;

        while select markUpTrans
            where markUpTrans.TransTableId == this.TableId
            &&    markUpTrans.TransRecId == this.RecId
            &&    !markUpTrans.TaxItemGroup
        {
            if (markUpTrans.RecId && this.TaxItemGroup)
            {
                ttsbegin;
                markUpTrans.selectForUpdate(true);
                markUpTrans.TaxItemGroup = this.TaxItemGroup;
                markUpTrans.update();
                ttscommit;
            }
        }

    }

    /// <summary>
    /// Clean up customer markup trans.
    /// </summary>
    public void cleanupCustMarkUp()
    {
        MarkupTrans     markUpTrans;
        while select markUpTrans
            where markUpTrans.TransTableId == this.TableId
            &&    markUpTrans.TransRecId == this.RecId
        {
            
            if (!this.markupCodeMappingExists(markUpTrans.MarkupCode))
            {
                ttsbegin;
                markUpTrans.selectForUpdate(true);
                markUpTrans.delete();
                ttscommit;
            }
        }

    }

    /// <summary>
    ///  Returns if the mark up code mapping exists 
    /// </summary>
    /// <param name="_purchMarkUpCode">
    /// The instance of <c>MarkupCode</c> table.
    /// </param>
    /// <returns>
    ///  Returns boolean value.
    /// </returns>
    public boolean markupCodeMappingExists(MarkupCode   _purchMarkUpCode)
    {
        boolean                                 ret;
        METCBCTPricingConditionChargesLinkTable ctPricingConditionChargesLinkTable;

        select firstonly MarkupCodeSales from ctPricingConditionChargesLinkTable
            where ctPricingConditionChargesLinkTable.MarkupCodePurch == _purchMarkUpCode;

        ret = ctPricingConditionChargesLinkTable.MarkupCodeSales ? true : false;

        return ret;
    }
